import { API, JsxEmit, ModuleKind, ModuleResolutionKind } from 'typescript/unstable/async';
import { readFileSync, readdirSync } from 'node:fs';
import { performance } from 'node:perf_hooks';
import { resolve } from 'node:path';
const cwd = resolve('.');
const opts = { strict: true, jsx: JsxEmit.ReactJSX, module: ModuleKind.ESNext, moduleResolution: ModuleResolutionKind.Bundler, skipLibCheck: true, noEmit: true };
const med = a => [...a].sort((x,y)=>x-y)[Math.floor(a.length/2)];
const ms = n => n.toFixed(1)+'ms';

async function run(label, files, target, alias) {
  console.log(`\n=== ${label} (${files.length} root files)`);
  const t0 = performance.now();
  const api = new API({ cwd, collectTiming: true });
  const program = await api.createProgram(files, opts);
  const tProg = performance.now();
  console.log('spawn+init+createProgram:', ms(tProg - t0));
  const text = readFileSync(target, 'utf8');
  const pos = text.indexOf(alias) + 1;
  // first checker touch = lazy check cost
  let t = performance.now();
  const ty = await program.checker.getTypeAtPosition(target, pos);
  console.log('first getTypeAtPosition (lazy check):', ms(performance.now() - t), '→', ty && await program.checker.typeToString(ty));
  // full "enrichment" walk: props of alias
  let reqs = 0; t = performance.now();
  const props = await program.checker.getPropertiesOfType(ty); reqs++;
  const names = props.map(p => p.name);
  const ptypes = await program.checker.getTypeOfSymbol(props); reqs++;           // batched
  const strs = []; for (const pt of ptypes) { strs.push(await program.checker.typeToString(pt)); reqs++; } // per-prop RTT
  const dt = performance.now() - t;
  console.log(`prop walk: ${props.length} props, ${reqs} requests, ${ms(dt)} (${ms(dt/reqs)}/req)`);
  console.log('sample props:', names.slice(0,4).join(','), '… e.g.', strs.slice(0,2));
  // warm RTT microbench: sequential
  const N = 500, lat = [];
  for (let i=0;i<N;i++){ const s=performance.now(); await program.checker.getTypeAtPosition(target, pos); lat.push(performance.now()-s); }
  console.log(`sequential getTypeAtPosition x${N}: median ${ms(med(lat))}, p95 ${ms([...lat].sort((a,b)=>a-b)[Math.floor(N*.95)])}`);
  // batched
  const ps = Array(N).fill(pos); t = performance.now();
  await program.checker.getTypeAtPosition(target, ps);
  console.log(`batched getTypeAtPosition x${N} in 1 request: ${ms(performance.now()-t)} (${ms((performance.now()-t)/N)}/item)`);
  const ti = await api.getTimingInfo();
  console.log('timing totals:', JSON.stringify(ti.totals));
  console.log('RSS (node client only):', (process.memoryUsage().rss/1e6).toFixed(0)+'MB');
  await api.close();
}
const small = [resolve('fixture/src/Button.tsx')];
await run('small', small, small[0], 'ButtonProps');
const wide = readdirSync('fixture/wide').map(f => resolve('fixture/wide', f));
await run('wide', wide, resolve('fixture/wide/C7.tsx'), 'CP7');
EOF
